#!/usr/bin/env bash
# Generate a working single-node (pseudo-distributed) Hadoop/YARN configuration sized for THIS machine's RAM,
# prepare passwordless SSH for start-dfs.sh and format the NameNode on first use.
#
#   bash setup/configure_hadoop.sh            write configs that do not exist yet / were generated by FraudLens
#   bash setup/configure_hadoop.sh --force    also replace hand-written configs (they are backed up first)
#   bash setup/configure_hadoop.sh --no-format  skip the one-time NameNode format
#
# The memory sizing prevents the classic small-VM failure where YARN jobs hang in PREP/ACCEPTED because the
# ApplicationMaster or a task container cannot be allocated.
set -euo pipefail

PROJECT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
FORCE=false; FORMAT=true
for arg in "$@"; do
    case "$arg" in
        --force) FORCE=true ;;
        --no-format) FORMAT=false ;;
        *) echo "Usage: $0 [--force] [--no-format]"; exit 1 ;;
    esac
done

[[ -f "$PROJECT/config/fraudlens.env" ]] && source "$PROJECT/config/fraudlens.env"
HADOOP_HOME="${HADOOP_HOME:-$HOME/hadoop}"
HADOOP_CONF_DIR="${HADOOP_CONF_DIR:-$HADOOP_HOME/etc/hadoop}"
if [[ ! -d "$HADOOP_CONF_DIR" ]]; then
    echo "ERROR: Hadoop configuration directory not found: $HADOOP_CONF_DIR"
    echo "Install Hadoop (setup/install_toolchain.sh) and run setup/configure_environment.sh first."
    exit 1
fi
if [[ -z "${JAVA_HOME:-}" || ! -x "$JAVA_HOME/bin/java" ]]; then
    echo "ERROR: JAVA_HOME is not set to a valid JDK. Run setup/configure_environment.sh first."
    exit 1
fi

DATA="${FRAUDLENS_DATA_DIR:-$HOME/hadoop_data}"
MARKER="generated by FraudLens setup/configure_hadoop.sh"
STAMP="$(date +%Y%m%d_%H%M%S)"
mkdir -p "$DATA/namenode" "$DATA/datanode" "$DATA/tmp"

# ---- memory sizing -------------------------------------------------------------
MEM_MB="${FRAUDLENS_MEM_MB:-$(awk '/MemTotal/ {print int($2/1024)}' /proc/meminfo)}"
NM_MB=$(( MEM_MB * 60 / 100 ))
(( NM_MB < 2048 )) && NM_MB=2048
(( NM_MB > 12288 )) && NM_MB=12288
if   (( NM_MB >= 6000 )); then TASK_MB=1536
elif (( NM_MB >= 3500 )); then TASK_MB=1024
else                           TASK_MB=768
fi
HEAP_MB=$(( TASK_MB * 80 / 100 ))
VCORES="$(nproc 2>/dev/null || echo 2)"; (( VCORES < 2 )) && VCORES=2
echo "Machine RAM ${MEM_MB} MB -> YARN NodeManager ${NM_MB} MB, task/AM containers ${TASK_MB} MB (heap ${HEAP_MB} MB), ${VCORES} vcores"

KEPT=0
write_conf() {   # write_conf <file name>   (content on stdin)
    local f="$HADOOP_CONF_DIR/$1" tmp
    tmp="$(mktemp)"; cat > "$tmp"
    if [[ -f "$f" ]] && ! grep -q "$MARKER" "$f"; then
        if [[ "$FORCE" == true ]]; then
            cp "$f" "$f.fraudlens-backup-$STAMP"
            echo "backed up existing $1 -> $1.fraudlens-backup-$STAMP"
        else
            echo "KEPT   $1 (hand-written; rerun with --force to replace it)"
            rm -f "$tmp"; KEPT=$((KEPT + 1)); return
        fi
    fi
    mv "$tmp" "$f"; chmod 644 "$f"; echo "wrote  $1"
}
prop() { printf '  <property><name>%s</name><value>%s</value></property>\n' "$1" "$2"; }
cfg_open()  { printf '<?xml version="1.0"?>\n<!-- %s -->\n<configuration>\n' "$MARKER"; }
cfg_close() { printf '</configuration>\n'; }

{ cfg_open
  prop fs.defaultFS "hdfs://localhost:9000"
  prop hadoop.tmp.dir "$DATA/tmp"
  cfg_close; } | write_conf core-site.xml

{ cfg_open
  prop dfs.replication 1
  prop dfs.namenode.name.dir "file://$DATA/namenode"
  prop dfs.datanode.data.dir "file://$DATA/datanode"
  cfg_close; } | write_conf hdfs-site.xml

{ cfg_open
  prop mapreduce.framework.name yarn
  prop mapreduce.application.classpath '$HADOOP_MAPRED_HOME/share/hadoop/mapreduce/*:$HADOOP_MAPRED_HOME/share/hadoop/mapreduce/lib/*'
  prop yarn.app.mapreduce.am.env "HADOOP_MAPRED_HOME=$HADOOP_HOME"
  prop mapreduce.map.env "HADOOP_MAPRED_HOME=$HADOOP_HOME"
  prop mapreduce.reduce.env "HADOOP_MAPRED_HOME=$HADOOP_HOME"
  prop yarn.app.mapreduce.am.resource.mb "$TASK_MB"
  prop yarn.app.mapreduce.am.command-opts "-Xmx${HEAP_MB}m"
  prop mapreduce.map.memory.mb "$TASK_MB"
  prop mapreduce.map.java.opts "-Xmx${HEAP_MB}m"
  prop mapreduce.reduce.memory.mb "$TASK_MB"
  prop mapreduce.reduce.java.opts "-Xmx${HEAP_MB}m"
  cfg_close; } | write_conf mapred-site.xml

{ cfg_open
  prop yarn.nodemanager.aux-services mapreduce_shuffle
  prop yarn.nodemanager.env-whitelist "JAVA_HOME,HADOOP_COMMON_HOME,HADOOP_HDFS_HOME,HADOOP_CONF_DIR,CLASSPATH_PREPEND_DISTCACHE,HADOOP_YARN_HOME,HADOOP_HOME,PATH,LANG,TZ,HADOOP_MAPRED_HOME"
  prop yarn.resourcemanager.hostname localhost
  prop yarn.nodemanager.resource.memory-mb "$NM_MB"
  prop yarn.nodemanager.resource.cpu-vcores "$VCORES"
  prop yarn.scheduler.minimum-allocation-mb 256
  prop yarn.scheduler.maximum-allocation-mb "$NM_MB"
  prop yarn.nodemanager.vmem-check-enabled false
  prop yarn.nodemanager.disk-health-checker.max-disk-utilization-per-disk-percentage 98
  cfg_close; } | write_conf yarn-site.xml

# The default AM share (10 percent) is smaller than one ApplicationMaster on a small node, so jobs never start.
{ cfg_open
  prop yarn.scheduler.capacity.maximum-applications 10000
  prop yarn.scheduler.capacity.maximum-am-resource-percent 0.6
  prop yarn.scheduler.capacity.resource-calculator org.apache.hadoop.yarn.util.resource.DefaultResourceCalculator
  prop yarn.scheduler.capacity.root.queues default
  prop yarn.scheduler.capacity.root.default.capacity 100
  prop yarn.scheduler.capacity.root.default.user-limit-factor 1
  prop yarn.scheduler.capacity.root.default.maximum-capacity 100
  prop yarn.scheduler.capacity.root.default.state RUNNING
  prop yarn.scheduler.capacity.root.default.acl_submit_applications '*'
  prop yarn.scheduler.capacity.root.default.acl_administer_queue '*'
  prop yarn.scheduler.capacity.node-locality-delay 40
  cfg_close; } | write_conf capacity-scheduler.xml

ENVSH="$HADOOP_CONF_DIR/hadoop-env.sh"
if [[ -f "$ENVSH" ]] && ! grep -q "FraudLens" "$ENVSH"; then
    printf '\n# FraudLens: Hadoop daemons started over SSH do not inherit JAVA_HOME\nexport JAVA_HOME=%s\n' "$JAVA_HOME" >> "$ENVSH"
    echo "added JAVA_HOME to hadoop-env.sh"
fi

# ---- SSH (start-dfs.sh / start-yarn.sh connect to localhost) ----------------------
if ! ssh -o BatchMode=yes -o StrictHostKeyChecking=accept-new localhost true 2>/dev/null; then
    echo "Setting up passwordless SSH to localhost ..."
    mkdir -p "$HOME/.ssh"; chmod 700 "$HOME/.ssh"
    [[ -f "$HOME/.ssh/id_rsa" ]] || ssh-keygen -q -t rsa -b 3072 -N '' -f "$HOME/.ssh/id_rsa"
    touch "$HOME/.ssh/authorized_keys"
    grep -qF "$(cat "$HOME/.ssh/id_rsa.pub")" "$HOME/.ssh/authorized_keys" || cat "$HOME/.ssh/id_rsa.pub" >> "$HOME/.ssh/authorized_keys"
    chmod 600 "$HOME/.ssh/authorized_keys"
    if ! (pgrep -x sshd >/dev/null 2>&1); then
        sudo systemctl enable --now ssh 2>/dev/null || sudo service ssh start || true
    fi
    sleep 1
    if ssh -o BatchMode=yes -o StrictHostKeyChecking=accept-new localhost true 2>/dev/null; then
        echo "SSH to localhost works."
    else
        echo "WARNING: passwordless SSH to localhost still fails. Check: sudo apt install openssh-server; sudo service ssh start"
    fi
fi

# ---- NameNode format (first run only) ------------------------------------------------
if [[ "$FORMAT" == true ]]; then
    if [[ -f "$DATA/namenode/current/VERSION" ]]; then
        echo "NameNode already formatted ($DATA/namenode); not formatting again."
    else
        echo "Formatting the NameNode (first run) ..."
        JAVA_HOME="$JAVA_HOME" HADOOP_CONF_DIR="$HADOOP_CONF_DIR" "$HADOOP_HOME/bin/hdfs" namenode -format -nonInteractive
    fi
fi

echo
if (( KEPT > 0 )); then
    echo "NOTE: $KEPT existing hand-written config file(s) were kept. If YARN jobs hang in PREP/ACCEPTED, compare them with"
    echo "      the recommended values above (NodeManager ${NM_MB} MB, containers ${TASK_MB} MB, max-am-resource-percent 0.6)"
    echo "      or rerun with --force (originals are backed up)."
fi
echo "Hadoop configuration ready in $HADOOP_CONF_DIR. Next: bash scripts/start_services.sh"
